namespace Dictora.Modules.Lessons.Infrastructure.YouTube;

internal sealed record CaptionTrackCandidate(string LanguageCode, bool IsAutoGenerated);

/// <summary>
/// Picks the English caption track (ADR-002): manual <c>en</c>, then manual <c>en-*</c>,
/// then auto-generated <c>en</c>, then auto-generated <c>en-*</c>. The first match wins on duplicates.
/// </summary>
internal static class CaptionTrackPicker
{
    /// <returns>The index of the chosen track, or <c>-1</c> if there's no English track.</returns>
    public static int PickEnglish(IReadOnlyList<CaptionTrackCandidate> tracks)
    {
        var bestIndex = -1;
        var bestRank = int.MaxValue;

        for (var i = 0; i < tracks.Count; i++)
        {
            if (Rank(tracks[i]) is { } rank && rank < bestRank)
            {
                (bestIndex, bestRank) = (i, rank);
            }
        }

        return bestIndex;
    }

    private static int? Rank(CaptionTrackCandidate track)
    {
        var code = track.LanguageCode;
        int? language = code.Equals("en", StringComparison.OrdinalIgnoreCase) ? 0
            : code.StartsWith("en-", StringComparison.OrdinalIgnoreCase) ? 1
            : null;

        return language + (track.IsAutoGenerated ? 2 : 0);
    }
}
